{"path": "wordy.py", "content": "import operator

OPS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied by": operator.mul,
    "divided by": None,
}


def _is_int(tok):
    try:
        int(tok)
        return True
    except ValueError:
        return False


def _div(a, b):
    if b == 0:
        raise ValueError("division by zero")
    return a // b if a % b == 0 else a / b


def answer(question):
    q = question.strip()
    if not q.startswith("What is"):
        raise ValueError("unknown operation")
    body = q[len("What is"):]
    if body.endswith("?"):
        body = body[:-1]
    body = body.replace("multiplied by", "multiplied_by").replace("divided by", "divided_by")
    tokens = body.split()
    if not tokens:
        raise ValueError("syntax error")
    if not _is_int(tokens[0]):
        raise ValueError("syntax error")
    result = int(tokens[0])
    i = 1
    while i < len(tokens):
        op = tokens[i].replace("_", " ")
        if _is_int(tokens[i]):
            raise ValueError("syntax error")
        if op not in OPS:
            raise ValueError("unknown operation")
        if i + 1 >= len(tokens) or not _is_int(tokens[i + 1]):
            raise ValueError("syntax error")
        n = int(tokens[i + 1])
        result = _div(result, n) if op == "divided by" else OPS[op](result, n)
        i += 2
    return result
"}

